import{_ as a,c as e,o as s,a5 as n}from"./chunks/framework.DorIfSpC.js";const i="/images/1-4%E7%90%A6%E7%90%A6.png",o="/images/%E7%90%A6%E7%90%A6_%E8%A1%A8%E6%83%85.jpeg",l="/images/%E7%90%A6%E7%90%A6%E5%BD%B1%E7%89%87.mp4",u=JSON.parse('{"title":"從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/ai-animation-workflow-blog"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/ai-animation-workflow-blog"}],["meta",{"property":"og:title","content":"從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流 | 星智未來"}],["meta",{"name":"twitter:title","content":"從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/ai-animation-workflow-blog\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/ai-animation-workflow-blog\\"}}"]]},"headers":[],"relativePath":"project/ai-animation-workflow-blog.md","filePath":"project/ai-animation-workflow-blog.md","lastUpdated":1788355070000}'),r={name:"project/ai-animation-workflow-blog.md"};function p(d,t,h,c,g,m){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="從劇本到成品-我用-ai-工具打造動畫短影片的完整工作流" tabindex="-1">從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流 <a class="header-anchor" href="#從劇本到成品-我用-ai-工具打造動畫短影片的完整工作流" aria-label="Permalink to &quot;從劇本到成品：我用 AI 工具打造動畫短影片的完整工作流&quot;">​</a></h1><blockquote><p>台灣的影視環境，拍一部片動輒數年，光劇本定稿就會搞個幾個月。但當 AI 工具越來越成熟，我們是不是可以用另一種方式說故事？</p></blockquote><p>這篇文章記錄了我和 Nicole（我太太，專業編劇）過去 10 天的 Side Project 探索。我們嘗試用 ComfyUI、Kling、ElevenLabs 等工具，將她寫的靈異懸疑劇本《靈體背後的故事》製作成 AI 動畫短影片。</p><p><strong>作者</strong>：Ray <strong>日期</strong>：2026 年 1 月 10 日</p><hr><h2 id="為什麼要做這件事" tabindex="-1">為什麼要做這件事？ <a class="header-anchor" href="#為什麼要做這件事" aria-label="Permalink to &quot;為什麼要做這件事？&quot;">​</a></h2><p>Nicole 是編劇出身，寫過不少劇本，但台灣影視產業的現實是：一個劇本從完成到開拍，可能要等上好幾年。有些好故事就這樣躺在抽屜裡。</p><p>我們的想法很簡單：<strong>既然 AI 生成影像的品質已經到了一定水準，何不試著用 AI 來「拍」她的劇本？</strong></p><p>目標不是取代真人拍攝，而是：</p><ul><li>快速驗證劇本的視覺呈現效果</li><li>累積短影片內容，建立系列 IP</li><li>探索 AI 影像創作的工作流程</li></ul><hr><h2 id="專案概覽-《靈體背後的故事》ep1" tabindex="-1">專案概覽：《靈體背後的故事》EP1 <a class="header-anchor" href="#專案概覽-《靈體背後的故事》ep1" aria-label="Permalink to &quot;專案概覽：《靈體背後的故事》EP1&quot;">​</a></h2><h3 id="故事簡介" tabindex="-1">故事簡介 <a class="header-anchor" href="#故事簡介" aria-label="Permalink to &quot;故事簡介&quot;">​</a></h3><p>室內設計師小莫能看見靈體，她的助理琦琦則有「幽靈嗅」——能聞到別人聞不到的味道。</p><p>一位失智老婦人請小莫裝修擱置十年的老公寓，要給兒子當結婚禮物。但當她們踏入那間公寓，琦琦開始頭暈、聞到燒香味，小莫則在陽台看見一個穿棕色外套的男人在抽煙......</p><p>這是一個關於雙胞胎兄弟、三角關係、背叛與死亡的故事。結局有個反轉：那真的是自殺嗎？</p><h3 id="角色設定" tabindex="-1">角色設定 <a class="header-anchor" href="#角色設定" aria-label="Permalink to &quot;角色設定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>角色</th><th>描述</th><th>參考形象</th></tr></thead><tbody><tr><td>小莫</td><td>35歲室內設計師，能看見靈體</td><td>專業幹練、短髮、溫暖眼神</td></tr><tr><td>琦琦</td><td>26歲助理，有幽靈嗅</td><td>參考雷嘉汭，知性文青風</td></tr><tr><td>老婦人</td><td>建澤母親，輕微失智</td><td>70歲、滄桑憔悴</td></tr><tr><td>哥哥</td><td>靈體，被背叛後上吊</td><td>棕色皮夾克、幽怨眼神</td></tr><tr><td>建澤</td><td>雙胞胎弟弟</td><td>與哥哥同臉，白襯衫</td></tr></tbody></table><p><img src="'+i+`" alt="琦琦定裝照"><em>琦琦定裝照：高丸子頭、圓框金屬眼鏡、米色風衣——經過數十次調整才確定的形象</em></p><hr><h2 id="工具組合與成本" tabindex="-1">工具組合與成本 <a class="header-anchor" href="#工具組合與成本" aria-label="Permalink to &quot;工具組合與成本&quot;">​</a></h2><p>經過這段時間的測試，我整理出以下工具組合：</p><table tabindex="0"><thead><tr><th>環節</th><th>工具</th><th>成本</th><th>備註</th></tr></thead><tbody><tr><td>角色圖片生成</td><td>ComfyUI + majicmixRealistic</td><td>免費</td><td>本地運行，需要顯卡</td></tr><tr><td>臉部一致性</td><td>IPAdapter PLUS FACE / FaceID</td><td>免費</td><td>ComfyUI 節點</td></tr><tr><td>表情變化</td><td>Google AI Studio + Gemini</td><td>免費額度</td><td>Nano Banana 模式</td></tr><tr><td>圖轉影片</td><td>Kling Video 2.6</td><td>訂閱制</td><td>img2video 效果驚艷</td></tr><tr><td>配音</td><td>ElevenLabs</td><td>訂閱制</td><td>支援聲紋克隆</td></tr><tr><td>對嘴同步</td><td>Kling Lip Sync</td><td>同上</td><td>關鍵！讓影片有說服力</td></tr><tr><td>剪輯</td><td>CapCut / 剪映</td><td>免費</td><td>加字幕、音效</td></tr></tbody></table><p><strong>重點發現</strong>：Kling 的 Video 2.6 img2video 效果真的很驚人，但它內建的語音功能不行。解決方案是用 Nicole 的聲音透過 ElevenLabs 做聲紋克隆生成配音，再用 <strong>Kling 的 Lip Sync</strong> 功能重新對嘴。這個組合才製作出覺得可以接受的影片片段。</p><hr><h2 id="核心工作流程" tabindex="-1">核心工作流程 <a class="header-anchor" href="#核心工作流程" aria-label="Permalink to &quot;核心工作流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>劇本 → 分鏡設計 → 角色定裝 → 關鍵幀生成 → 圖轉影片 → 配音對嘴 → 剪輯合成</span></span></code></pre></div><h3 id="step-1-角色定裝-最花時間的環節" tabindex="-1">Step 1：角色定裝（最花時間的環節） <a class="header-anchor" href="#step-1-角色定裝-最花時間的環節" aria-label="Permalink to &quot;Step 1：角色定裝（最花時間的環節）&quot;">​</a></h3><p>角色一致性是 AI 動畫最大的挑戰。以琦琦這個角色為例：</p><p><strong>設定目標</strong>：參考雷嘉汭的形象，知性文青風，圓框金屬眼鏡，高丸子頭。</p><p><strong>ComfyUI 配置</strong>：</p><ul><li>模型：majicmixRealistic_v7</li><li>FaceID：FACEID PLUS V2（比 PLUS FACE 更準確）</li><li>IPAdapter weight：0.90</li><li>ControlNet：control_v11p_sd15_openpose（強度 0.20）</li></ul><p><strong>調了多少張</strong>：數十張。真的沒有捷徑，就是不斷調整 prompt、seed、weight，直到找到滿意的結果。</p><p><strong>關鍵 Prompt 結構</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>masterpiece, best quality, photorealistic, highly detailed skin texture,</span></span>
<span class="line"><span>upper body portrait, 1girl, young East Asian woman, early 20s,</span></span>
<span class="line"><span>[臉部特徵], [眼鏡描述], [髮型], [服裝],</span></span></code></pre></div><p><strong>負面 Prompt 同樣重要</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>heavy makeup, glamorous, sexy, seductive, black frame glasses, </span></span>
<span class="line"><span>thick frame glasses, no glasses, long hair down, cartoon, anime, </span></span>
<span class="line"><span>deformed face, bad anatomy, blurry</span></span></code></pre></div><h3 id="step-2-表情變化-gemini-的妙用" tabindex="-1">Step 2：表情變化（Gemini 的妙用） <a class="header-anchor" href="#step-2-表情變化-gemini-的妙用" aria-label="Permalink to &quot;Step 2：表情變化（Gemini 的妙用）&quot;">​</a></h3><p>一開始我用 ComfyUI 生成不同表情，但一致性很難控制。</p><p>後來發現 <strong>Google AI Studio 的 Playground</strong> 搭配 Gemini 2.5 Flash Image（Nano Banana 模式），效果好很多。</p><p>用中文 prompt 就可以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>角色表情參考圖，26歲亞洲女性，高丸子頭，圓形金色金屬框眼鏡，</span></span>
<span class="line"><span>濃眉，眼神深邃，米色風衣外套，奶油色襯衫內搭。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以 2x3 格子呈現 6 種表情：</span></span>
<span class="line"><span>1. 平靜</span></span>
<span class="line"><span>2. 好奇疑惑</span></span>
<span class="line"><span>3. 害怕驚嚇</span></span>
<span class="line"><span>4. 頭暈不適</span></span>
<span class="line"><span>5. 震驚恐懼</span></span>
<span class="line"><span>6. 驚訝難以置信</span></span>
<span class="line"><span></span></span>
<span class="line"><span>白色背景，角色設計一致，寫實風格</span></span></code></pre></div><p>這個方法生成的表情一致性比 ComfyUI 好控制，而且速度更快。</p><p><img src="`+o+'" alt="琦琦表情變化"><em>用 Gemini AI Studio 生成的琦琦表情變化：從平靜、疑惑、害怕到震驚，角色一致性相當穩定</em></p><h3 id="step-3-圖轉影片-kling-的威力" tabindex="-1">Step 3：圖轉影片（Kling 的威力） <a class="header-anchor" href="#step-3-圖轉影片-kling-的威力" aria-label="Permalink to &quot;Step 3：圖轉影片（Kling 的威力）&quot;">​</a></h3><p>Kling Video 2.6 的 img2video 功能是目前我測試過效果最好的。</p><p>給它一張定裝照，加上動作描述，它能生成相當自然的動態。但有幾個注意事項：</p><ul><li>不要期待太複雜的動作</li><li>5 秒左右的片段品質最穩定</li><li>臉部表情變化要小心，容易崩壞</li></ul><h3 id="step-4-配音與對嘴-關鍵一步" tabindex="-1">Step 4：配音與對嘴（關鍵一步） <a class="header-anchor" href="#step-4-配音與對嘴-關鍵一步" aria-label="Permalink to &quot;Step 4：配音與對嘴（關鍵一步）&quot;">​</a></h3><p>這是讓影片從「AI 感很重」變成「還可以看」的關鍵。</p><p><strong>配音流程</strong>：</p><ol><li>Nicole 錄製 1 分多鐘的聲音樣本</li><li>用 ElevenLabs 做聲紋克隆（Voice Clone）</li><li>輸入台詞文字，生成配音音檔</li><li>用 <strong>Kling Lip Sync</strong> 將配音與影片對嘴同步</li></ol><video controls width="100%"><source src="'+l+`" type="video/mp4"></video> *實際成果：琦琦說台詞的片段，配音來自 Nicole 的聲紋克隆，對嘴使用 Kling Lip Sync* <p><strong>台詞小技巧</strong>：為了保持台灣口音的自然感，台詞要加入語氣詞：</p><table tabindex="0"><thead><tr><th>語氣詞</th><th>範例</th></tr></thead><tbody><tr><td>啦</td><td>「沒事沒事啦」</td></tr><tr><td>耶</td><td>「我什麼都沒看到耶」</td></tr><tr><td>喔</td><td>「頭好暈喔」</td></tr><tr><td>欸</td><td>「欸等等」</td></tr><tr><td>蛤</td><td>「蛤？怎麼會？」</td></tr></tbody></table><p>測試通過的台詞範本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>突然頭好暈喔，大概太久沒爬那麼多層樓梯了啦，沒事沒事。</span></span>
<span class="line"><span>超煩的耶，你知道我最怕老鼠了啦！</span></span>
<span class="line"><span>欸等等，妳有聞到燒香的味道嗎？</span></span></code></pre></div><hr><h2 id="視覺風格設定" tabindex="-1">視覺風格設定 <a class="header-anchor" href="#視覺風格設定" aria-label="Permalink to &quot;視覺風格設定&quot;">​</a></h2><p>為了維持系列的一致性，我們定義了幾個視覺規則：</p><h3 id="色調分類" tabindex="-1">色調分類 <a class="header-anchor" href="#色調分類" aria-label="Permalink to &quot;色調分類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>場景類型</th><th>色調風格</th></tr></thead><tbody><tr><td>現實場景</td><td>自然光、暖色點綴</td></tr><tr><td>靈異場景</td><td>青灰色調、低飽和度、對比強烈</td></tr><tr><td>回憶場景</td><td>褪色濾鏡、顆粒感</td></tr></tbody></table><h3 id="j-horror-風格模板" tabindex="-1">J-Horror 風格模板 <a class="header-anchor" href="#j-horror-風格模板" aria-label="Permalink to &quot;J-Horror 風格模板&quot;">​</a></h3><p>針對恐怖場景，我們建立了標準化的 prompt 模板：</p><p><strong>場景 Prompt</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>old cluttered japanese apartment, dim green fluorescent light, </span></span>
<span class="line"><span>warm yellow lamp in background, scattered papers and debris on floor, </span></span>
<span class="line"><span>peeling walls, dusty atmosphere, deep shadows, muted desaturated colors, </span></span>
<span class="line"><span>film grain, j-horror atmosphere</span></span></code></pre></div><p><strong>人物負面 Prompt</strong>（避免太漂亮、太性感）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bare shoulders, exposed skin, off shoulder, sexy, seductive, beautiful, </span></span>
<span class="line"><span>pretty, glamorous, red lipstick, makeup, happy, smiling, deformed face</span></span></code></pre></div><h3 id="服裝注意事項" tabindex="-1">服裝注意事項 <a class="header-anchor" href="#服裝注意事項" aria-label="Permalink to &quot;服裝注意事項&quot;">​</a></h3><p>AI 生成人物時，露肩問題很常見。解決方案是在 prompt 裡明確指定：</p><table tabindex="0"><thead><tr><th>建議使用</th><th>避免使用</th></tr></thead><tbody><tr><td>high neck sweater</td><td>knit sweater</td></tr><tr><td>crewneck sweater</td><td>off shoulder</td></tr><tr><td>hoodie</td><td>loose sweater</td></tr><tr><td>zip-up jacket</td><td>-</td></tr></tbody></table><hr><h2 id="目前的成果與挑戰" tabindex="-1">目前的成果與挑戰 <a class="header-anchor" href="#目前的成果與挑戰" aria-label="Permalink to &quot;目前的成果與挑戰&quot;">​</a></h2><h3 id="做到了什麼" tabindex="-1">做到了什麼 <a class="header-anchor" href="#做到了什麼" aria-label="Permalink to &quot;做到了什麼&quot;">​</a></h3><ul><li>完成 6 個主要角色的定裝設定</li><li>建立可重複使用的 ComfyUI workflow</li><li>製作出第一個 5 秒的測試片段（配音 + 對嘴）</li><li>整理出完整的角色 prompt 文件</li></ul><h3 id="還在解決的問題" tabindex="-1">還在解決的問題 <a class="header-anchor" href="#還在解決的問題" aria-label="Permalink to &quot;還在解決的問題&quot;">​</a></h3><ol><li><strong>角色一致性</strong>：跨場景時臉還是會飄移，需要更多 IPAdapter 調整</li><li><strong>動作連貫性</strong>：5 秒以上的動作容易出問題</li><li><strong>全身構圖</strong>：腳部容易變形，需要 Inpainting 修復</li><li><strong>效率</strong>：單一場景的完整製作流程還是太長</li></ol><hr><h2 id="下一步計畫" tabindex="-1">下一步計畫 <a class="header-anchor" href="#下一步計畫" aria-label="Permalink to &quot;下一步計畫&quot;">​</a></h2><ul><li>[ ] 完成 EP1 場景 1-3 的完整影片</li><li>[ ] 建立固定片頭片尾模板</li><li>[ ] 探索批次生成的可能性</li><li>[ ] 建立整部影片生成工作流的統一平台</li></ul><hr><h2 id="給想嘗試的人的建議" tabindex="-1">給想嘗試的人的建議 <a class="header-anchor" href="#給想嘗試的人的建議" aria-label="Permalink to &quot;給想嘗試的人的建議&quot;">​</a></h2><ol><li><p><strong>從角色定裝開始</strong>：這是最花時間但最重要的一步。沒有穩定的角色，後面都是白做。</p></li><li><p><strong>善用 Seed</strong>：找到滿意的結果後，一定要記錄 seed。我們每個角色都有完整的參數記錄。</p></li><li><p><strong>不要只用一種工具</strong>：ComfyUI 做基礎生成，Gemini 做表情變化，Kling 做影片，ElevenLabs 做配音——組合起來效果最好。</p></li><li><p><strong>接受「還可以」</strong>：AI 生成的影片目前還達不到專業影視水準，但作為短影片內容，已經足夠引起觀眾興趣了。</p></li><li><p><strong>保持系統性</strong>：建立文件、記錄參數、整理 workflow。這不是做一次就結束的事，而是要能重複使用。</p></li></ol><hr><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>這 10 天的探索讓我確信：AI 動畫短影片是一個可行的創作形式。</p><p>它不會取代真人影視製作，但它提供了另一種可能——讓那些躺在抽屜裡的劇本，有機會用另一種方式被看見。</p><p>對 Nicole 來說，這是一個驗證創意的快速通道。對我來說，這是一個結合技術與創意的有趣實驗。</p><p>我們會持續更新這個專案的進度。如果你也在做類似的嘗試，歡迎交流。</p><hr><p><em>專案持續更新中</em><em>InsightCosmos | blog.aidream.com.tw</em></p>`,92)])])}const k=a(r,[["render",p]]);export{u as __pageData,k as default};
